}

// Tab switching
function showTab(tabId) {
    // Deactivate all nav buttons and tabs
    document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
    document.querySelectorAll('.tab').forEach(tab => tab.classList.remove('active'));

    // Activate the selected tab and button
    document.querySelector(`#tab-${tabId}`).classList.add('active');
    document.querySelector(`.nav-btn[onclick*="${tabId}"]`).classList.add('active');
}

// LeetCode Stats Loading
async function loadLeetCodeStats() {
    const username = document.getElementById('leetcodeUser').value;
    if (!username) {
        alert('Please enter a LeetCode username.');
        return;
    }

    try {
        const response = await fetch(`http://localhost:5000/leetcode/${username}`);
        if (!response.ok) {
            const errorData = await response.json();
            alert(`Error fetching LeetCode stats: ${errorData.error}`);
            return;
        }
        const data = await response.json();

        // Update Dashboard metrics
        document.getElementById('m-solved').textContent = data.solved;
        document.getElementById('easy-count').textContent = data.easy;
        document.getElementById('medium-count').textContent = data.medium;
        document.getElementById('hard-count').textContent = data.hard;

        // Calculate a simple readiness percentage (e.g., based on solved problems)
        const totalPossibleProblems = 500; // Arbitrary max for readiness calculation
        const readinessPercentage = Math.min(100, Math.round((data.solved / totalPossibleProblems) * 100));

        document.getElementById('m-ready').textContent = `${readinessPercentage}%`;
        document.getElementById('m-ready-label').textContent = data.level; // Using 'level' from backend

        // Update ring chart
        document.getElementById('ring-pct').textContent = `${readinessPercentage}%`;
        const circumference = 2 * Math.PI * 40; // r=40 from SVG
        const offset = circumference - (readinessPercentage / 100) * circumference;
        document.getElementById('ring-arc').style.strokeDashoffset = offset;

        // Placeholder for topics practiced and weak topics
        document.getElementById('m-topics').textContent = Math.min(data.solved > 0 ? 1 : 0, 17); // Simple heuristic
        document.getElementById('total-topics').textContent = 17; // Fixed for now
        document.getElementById('m-weak').textContent = data.solved > 10 ? 1 : 0; // Simple heuristic

    } catch (error) {
        console.error('Error:', error);
        alert('Failed to load LeetCode stats. Check console for details.');
    }
}

// Initial tab load (Dashboard) and LeetCode stats load
document.addEventListener('DOMContentLoaded', () => {
    showTab('dashboard');
    loadLeetCodeStats(); // Load stats on initial page load
});
"}

